/*
 * A288753  Positions of 0 in A288752; complement of A288754.
 * https://oeis.org/A288753
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, easy
 * Formula:   a(n) = position of the n-th 0 in A288752 (word generated by
 *            00->0110, 1->01 from "00", odd iterations); computed by
 *            iterating the rewriting and scanning
 * Range:     u8 n <= 139, u16 n <= 10000, u32 n <= 10000, u64 n <= 10000,
 *            u128 n <= 10000, big any n
 * Validated: standard, pass, 79 terms through n = 9633 (2026-11-08)
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdlib.h>
#include <stddef.h>

static char *A288753_w = NULL;
static size_t A288753_len = 0;
static size_t A288753_zeros = 0;

static void A288753_step(void)
{
    size_t cap = A288753_len * 4 + 4;
    char *nx = (char *)malloc(cap);
    size_t j = 0;
    for (size_t i = 0; i < A288753_len; ) {
        if (A288753_w[i] == '0' && (i + 1) < A288753_len && A288753_w[i + 1] == '0') {
            nx[j++] = '0'; nx[j++] = '1'; nx[j++] = '1'; nx[j++] = '0';
            i += 2;
        } else if (A288753_w[i] == '0') {
            nx[j++] = '0';
            ++i;
        } else {
            nx[j++] = '0'; nx[j++] = '1';
            ++i;
        }
    }
    free(A288753_w);
    A288753_w = nx;
    A288753_len = j;
}

static void A288753_count(void)
{
    size_t z = 0;
    for (size_t i = 0; i < A288753_len; i++) if (A288753_w[i] == '0') z++;
    A288753_zeros = z;
}

seq_t a(idx_t n)
{
    if (n < 1) return (seq_t)0;
    if (!A288753_w) {
        A288753_w = (char *)malloc(4);
        A288753_w[0] = '0'; A288753_w[1] = '1'; A288753_w[2] = '1'; A288753_w[3] = '0';
        A288753_len = 4;
        A288753_count();
    }
    while ((idx_t)A288753_zeros < n) {
        A288753_step();
        A288753_step();
        A288753_count();
    }
    idx_t c = 0;
    for (size_t i = 0; i < A288753_len; i++) {
        if (A288753_w[i] == '0') {
            c++;
            if (c == n) return (seq_t)(i + 1);
        }
    }
    return (seq_t)0;
}
